>> +	self->pagemap_fd = open("/proc/self/pagemap", O_RDONLY);
>> +	if (self->pagemap_fd < 0)
>> +		SKIP(return, "Cannot open /proc/self/pagemap\n");
>> +
>> +	if (!swap_available(self->pmd_size))
